seq = open('region.fasta').read()
s = ''.join(seq.strip().split('\n')[1:])
L=len(s)
def rc(x): return x.translate(str.maketrans('ACGT','TGCA'))[::-1]
t=rc(s)  # reverse complement

def frame_orfs(seq,strand):
    out=[]
    for f in range(3):
        last=f
        for j in range(f,L-2,3):
            if seq[j:j+3] in ('TAA','TAG','TGA'):
                start=last
                if j-start>=150:  # >=50 codons
                    out.append((start+1,j+3,(j-start)//3,strand, seq[start:j]))
                last=j+3
        if L-last>=150:
            out.append((last+1,L,(L-last)//3,strand+'_trunc',seq[last:]))
    return out

res=frame_orfs(s,'+')+frame_orfs(t,'-')
# for '-' strand, convert coords to forward
conv=[]
for st,en,aa,strand,frag in res:
    if strand.startswith('-'):
        nst, nen = L-en+1, L-st+1
    else:
        nst,nen=st,en
    conv.append((nst,nen,aa,strand,frag))
conv.sort(key=lambda x:-x[2])
for c in conv:
    print(c[0],c[1],c[2],c[3], 'GC %.2f'%((c[4].count('G')+c[4].count('C'))/len(c[4])))
"}

